import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String s = st.nextToken();
        int[] girls = new int[s.length()]; // unmatched girls; the top is the nearest one ahead
        int top = 0;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n && i < s.length(); i++) {
            if (s.charAt(i) == '0') { girls[top++] = i + 1; continue; }
            if (out.length() > 0) out.append(' ');
            out.append(top > 0 ? girls[--top] : -1);
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	r := bufio.NewReaderSize(os.Stdin, 1<<20)
	var n int
	var s string
	fmt.Fscan(r, &n, &s)
	var girls []int // unmatched girls; the top is the nearest one ahead
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	first := true
	for i := 0; i < n && i < len(s); i++ {
		if s[i] == '0' {
			girls = append(girls, i+1)
			continue
		}
		g := -1
		if len(girls) > 0 {
			g = girls[len(girls)-1]
			girls = girls[:len(girls)-1]
		}
		if !first {
			w.WriteByte(' ')
		}
		first = false
		w.WriteString(strconv.Itoa(g))
	}
	w.WriteByte('\n')
}
